"use server";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { FounderRepositories } from "../../../../../data/repositories/founderRepositories";
import { loadApplicationRuntimeBindings } from "../../../../../application/runtime/ApplicationCanonicalRuntime";
import { buildDexaAppointmentDraftFromFormData,createDexaAppointmentManagementService,DEXA_APPOINTMENT_ID } from "../../../../../domain/services/DexaAppointmentManagementService";
export async function saveDexaAppointment(context,_state,formData){const draft=buildDexaAppointmentDraftFromFormData(formData);const user=await FounderRepositories.users.getCurrentUser();const existing=await FounderRepositories.executionItems.getExecutionItemById(DEXA_APPOINTMENT_ID);if(existing&&Number(context.expectedRevision)!==Number(existing.executionRevision)||!existing&&context.expectedRevision!=null)return{message:"This schedule changed while you were editing it. Review the latest version and try again.",values:draft};const goal=(await FounderRepositories.goals.listGoals(user.id)).find((item)=>item.primary&&item.status==="active");const timezone=user.timezone??"America/Los_Angeles";const result=await createDexaAppointmentManagementService({...await loadApplicationRuntimeBindings()}).save({userId:user.id,goalId:goal?.id??null,timezone,expectedRevision:existing?.executionRevision??null,draft,author:{type:"user",id:user.id,displayName:user.displayName??"Founder"}});if(result.outcome!=="success")return{message:result.reason,values:draft};revalidatePath("/profile/operating-plan/execution/dexa","page");revalidatePath("/profile/operating-plan/execution/dexa?edit=1","page");revalidatePath("/profile/operating-plan","page");redirect("/profile/operating-plan/execution/dexa");}
